import random

from solution import words_in_sentence


def is_prime_oracle(n):
    if n < 2:
        return False
    divisor = 2
    while divisor * divisor <= n:
        if n % divisor == 0:
            return False
        divisor += 1
    return True


def oracle(sentence):
    return " ".join(
        word for word in sentence.split(" ") if is_prime_oracle(len(word))
    )


